package app

import (
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strconv"
	"strings"

	"dzsj-kv-sync/internal/kv"
)

type PairConfig struct {
	Name      string `json:"name"`
	StatsPath string `json:"statsPath"`
	RawPath   string `json:"rawPath"`
}

type FieldMeta struct {
	Base              string `json:"base,omitempty"`
	FallbackLocalized string `json:"fallbackLocalized,omitempty"`
}

type PluginConfig struct {
	Pairs              []PairConfig
	FieldTable         map[string]FieldMeta
	FieldTableOrder    []string
	FieldTable2        map[string]FieldMeta
	FieldTable2Order   []string
	LocalizationFile   string
	LocalizationLookup []string
	EnsurePlusSpace    bool
	Level              map[string]any
	PlayerStatsFile    string
}

type loadedConfig struct {
	cfg     *PluginConfig
	cfgPath string
}

type insertIndexRef struct {
	Value int
}

func Run(workspaceRoot string) error {
	loaded, err := loadConfig(workspaceRoot)
	if err != nil {
		return err
	}
	cfg := loaded.cfg
	cfgDir := filepath.Dir(loaded.cfgPath)
	cfgParent := filepath.Dir(cfgDir)

	baseCandidates := uniqueNonEmpty([]string{
		workspaceRoot,
		cfgDir,
		cfgParent,
	})

	resolvePath := func(rel string, forWrite bool) string {
		// game/... 优先尝试父级工作区（避免写到 repo 内的 game 目录）
		var order []string
		if strings.HasPrefix(rel, "game/") || strings.HasPrefix(rel, "game\\") {
			seen := map[string]struct{}{}
			if cfgParent != "" {
				order = append(order, cfgParent)
				seen[cfgParent] = struct{}{}
			}
			for _, b := range baseCandidates {
				if _, ok := seen[b]; ok {
					continue
				}
				order = append(order, b)
			}
		} else {
			order = baseCandidates
		}

