type localizeBaseItemsParams struct {
	pairName      string
	rawItemOrder  []string
	statsItems    *kv.KVObject
	rawItems      *kv.KVObject
	locKV         *kv.KVObject
	locText       string
	insertByIndex func(string, *insertIndexRef, []locEntry) string
	buildTooltip  func(string, *kv.KVObject) string
	getBonusOrder func(string) []string
	insertRef     *insertIndexRef
}

type locEntry struct {
	key   string
	value string
}

type localizeResult struct {
	locText   string
	insertRef *insertIndexRef
}

func localizeBaseItems(p localizeBaseItemsParams) localizeResult {
	locText := p.locText
	insertRef := p.insertRef

	if insertRef == nil {
		firstItem := p.rawItemOrder[0]
		bonusOrder := p.getBonusOrder(firstItem)
		if len(bonusOrder) > 0 {
			anchor := fmt.Sprintf(`DOTA_Tooltip_Ability_%s_%s`, firstItem, bonusOrder[0])
			re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
			if m := re.FindStringSubmatchIndex(locText); m != nil {
				body := locText[m[2]:m[3]]
				lines := strings.Split(body, "\n")
				for i, line := range lines {
					if strings.Contains(line, fmt.Sprintf(`"%s"`, anchor)) {
						insertRef = &insertIndexRef{Value: i + 1}
						break
					}
				}
			}
		}
	}

	if insertRef == nil {
		return localizeResult{locText: locText, insertRef: nil}
	}

	for _, itemName := range p.rawItemOrder {
		statsItem, _ := p.statsItems.GetObject(itemName)
		rawItem, _ := p.rawItems.GetObject(itemName)
		if statsItem == nil || rawItem == nil {
			continue
		}
		abilityValues, _ := rawItem.GetObject("AbilityValues")
		locEntries := []locEntry{}
		desiredKeys := map[string]struct{}{}
		ordered := buildOrderedFields(abilityValues, statsItem, p.getBonusOrder(itemName))
		for _, field := range ordered {
			if field != "Level" {
				if bonus, ok := statsItem.GetObject("BonusAttribute"); ok && bonus != nil {
					if _, ok := bonus.Get(field); !ok {
						continue
					}
				}
			}

			locKey := fmt.Sprintf(`DOTA_Tooltip_Ability_%s_%s`, itemName, field)
			desiredKeys[locKey] = struct{}{}
			if strings.Contains(locText, fmt.Sprintf(`"%s"`, locKey)) {
				continue
			}
			val := p.buildTooltip(field, p.locKV)
			if val == "" {
				continue
			}
			locEntries = append(locEntries, locEntry{key: locKey, value: val})
		}

		if len(desiredKeys) > 0 {
			locText = removeStaleAttributeLocalization(locText, insertRef, itemName, desiredKeys)
		}
		if len(locEntries) > 0 {
			locText = p.insertByIndex(locText, insertRef, locEntries)
		}
	}

	return localizeResult{locText: locText, insertRef: insertRef}
}

func buildOrderedFields(av *kv.KVObject, statsItem *kv.KVObject, bonusOrder []string) []string {
	if av == nil {
		return []string{}
	}
	if len(bonusOrder) > 0 {
		order := append([]string{}, bonusOrder...)
		if av.Has("Level") && !contains(order, "Level") {
			order = append(order, "Level")
		}
		return order
	}
	if statsItem == nil {
		return []string{}
	}
	if bonus, ok := statsItem.GetObject("BonusAttribute"); ok && bonus != nil {
		order := append([]string{}, bonus.Keys...)
		if av.Has("Level") && !contains(order, "Level") {
			order = append(order, "Level")
		}
		return order
	}
	return []string{}
}

func contains(arr []string, k string) bool {
	for _, v := range arr {
		if v == k {
			return true
		}
	}
	return false
}

func removeStaleAttributeLocalization(locText string, insertRef *insertIndexRef, itemName string, desiredKeys map[string]struct{}) string {
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText
	}
	body := locText[m[2]:m[3]]
	bodyStart := m[2]
	bodyEnd := m[3]

	lines := strings.Split(body, "\n")
	prefix := fmt.Sprintf("DOTA_Tooltip_Ability_%s_", itemName)
	removed := []int{}
	kept := make([]string, 0, len(lines))
	for idx, line := range lines {
		m := regexp.MustCompile(`^\s*"([^"]+)"`).FindStringSubmatch(line)
		if len(m) != 2 {
			kept = append(kept, line)
			continue
		}
		key := m[1]
		if !strings.HasPrefix(key, prefix) {
			kept = append(kept, line)
			continue
		}
		if _, ok := desiredKeys[key]; ok {
			kept = append(kept, line)
			continue
		}
		suffix := strings.TrimPrefix(key, prefix)
		if shouldKeepNonAttributeSuffix(suffix) {
			kept = append(kept, line)
			continue
		}
		removed = append(removed, idx)
	}

	if len(removed) == 0 {
		return locText
	}

	if insertRef != nil {
		count := 0
		for _, idx := range removed {
			if idx < insertRef.Value {
				count++
			}
		}
		insertRef.Value = max(0, insertRef.Value-count)
	}

	newBody := strings.Join(kept, "\n")
	return locText[:bodyStart] + newBody + locText[bodyEnd:]
}

func shouldKeepNonAttributeSuffix(suffix string) bool {
	if strings.HasSuffix(suffix, "Description") {
		return true
	}
	if strings.Contains(suffix, "SummaryDescription") {
		return true
	}
	return suffix == "Lore" || suffix == "Notes" || suffix == "Note"
}

