func expandLocalizationByLevel(p expandLocalizationParams) string {
	locText := p.locText
	for _, itemName := range p.rawItemOrder {
		rawItem, _ := p.rawItems.GetObject(itemName)
		statsItem, _ := p.statsItems.GetObject(itemName)
		if rawItem == nil || statsItem == nil {
			continue
		}
		av, _ := rawItem.GetObject("AbilityValues")
		if av == nil {
			continue
		}
		maxLevel := p.maxLevelMap[itemName]
		if maxLevel <= 1 {
			continue
		}
		bonus, _ := statsItem.GetObject("BonusAttribute")
		ordered := buildOrderedFields2(av, bonus)
		insertRef := p.insertRef
		if insertRef == nil {
			insertRef = deriveInsertRef(locText, itemName, p.insertRef)
		}
		// use a working copy to avoid moving caller's ref unexpectedly
		refCopy := &insertIndexRef{Value: insertRef.Value}
		for lvl := 1; lvl <= maxLevel; lvl++ {
			entries := []locEntry{}
			for _, field := range ordered {
				if field != "Level" && bonus != nil {
					if _, ok := bonus.Get(field); !ok {
						continue
					}
				}
				locKey := fmt.Sprintf("DOTA_Tooltip_Ability_%s_%d_%s", itemName, lvl, field)
				if strings.Contains(locText, fmt.Sprintf(`"%s"`, locKey)) {
					continue
				}
				val := p.buildTooltip(field, p.locKV)
				if val == "" {
					continue
				}
				entries = append(entries, locEntry{key: locKey, value: val})
			}
			if len(entries) > 0 {
				locText = p.insertByIndex(locText, refCopy, entries)
			}
		}
		if p.insertRef != nil {
			p.insertRef.Value = refCopy.Value
		}

		sections := []string{
			"",
			"_Description",
			"_Lore",
			"_SummaryDescription",
			"_SummaryDescription_LevelUp",
		}
		for _, suf := range sections {
			baseKey := fmt.Sprintf("DOTA_Tooltip_Ability_%s%s", itemName, suf)
			re := regexp.MustCompile(fmt.Sprintf(`"%s"\s+"([^"]*)"`, regexp.QuoteMeta(baseKey)))
			m := re.FindStringSubmatch(locText)
			if len(m) != 2 {
				continue
			}
			value := m[1]
			newLines := []string{}
			for lvl := 1; lvl <= maxLevel; lvl++ {
				newKey := fmt.Sprintf("DOTA_Tooltip_Ability_%s_%d%s", itemName, lvl, suf)
				if strings.Contains(locText, fmt.Sprintf(`"%s"`, newKey)) {
					continue
				}
				newLines = append(newLines, fmt.Sprintf(`        "%s" "%s"`, newKey, value))
			}
			if len(newLines) > 0 {
				locText = insertAfterKey(locText, baseKey, newLines)
			}
		}
	}
	return locText
}

func buildOrderedFields2(av *kv.KVObject, bonus kv.KVValue) []string {
	if av == nil {
		return []string{}
	}
	if bObj, ok := kv.IsObject(bonus); ok && bObj != nil {
		order := append([]string{}, bObj.Keys...)
		if av.Has("Level") && !contains(order, "Level") {
			order = append(order, "Level")
		}
		return order
	}
	return []string{}
}

func insertAfterKey(locText, baseKey string, newLines []string) string {
	if len(newLines) == 0 {
		return locText
	}
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText
	}
	body := locText[m[2]:m[3]]
	lines := strings.Split(body, "\n")
	idx := -1
	for i, line := range lines {
		if strings.Contains(line, fmt.Sprintf(`"%s"`, baseKey)) {
			idx = i
			break
		}
	}
	if idx == -1 {
		return locText
	}
	result := append([]string{}, lines[:idx+1]...)
	result = append(result, newLines...)
	result = append(result, lines[idx+1:]...)
	bodyStart := m[2]
	bodyEnd := m[3]
	return locText[:bodyStart] + strings.Join(result, "\n") + locText[bodyEnd:]
}

func insertLocalizationByIndex(locText string, ref *insertIndexRef, entries []locEntry) string {
	if len(entries) == 0 {
		return locText
	}
	if ref == nil {
		return locText
	}
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText
	}
	body := locText[m[2]:m[3]]
	bodyStart := m[2]
	bodyEnd := m[3]
	lines := strings.Split(body, "\n")
	insertLines := make([]string, len(entries))
	for i, e := range entries {
		insertLines[i] = fmt.Sprintf(`        "%s" "%s"`, e.key, e.value)
	}
	idx := ref.Value
	if idx < 0 {
		idx = 0
	}
	if idx > len(lines) {
		idx = len(lines)
	}
	newLines := append([]string{}, lines[:idx]...)
	newLines = append(newLines, insertLines...)
	newLines = append(newLines, lines[idx:]...)
	ref.Value += len(insertLines)
	newBody := strings.Join(newLines, "\n")
	return locText[:bodyStart] + newBody + locText[bodyEnd:]
}

