	for i, line := range lines {
		if strings.Contains(line, prefix) {
			lastIdx = i
		}
	}

	if lastIdx >= 0 {
		return &insertIndexRef{Value: lastIdx + 1}
	}
	if global != nil {
		return &insertIndexRef{Value: global.Value}
	}
	return &insertIndexRef{Value: len(lines)}
}

// trimTokensTrailingBlankLines removes trailing blank lines at the end of Tokens block.
func normalizeTokensBlankLines(locText string) string {
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText
	}
	body := locText[m[2]:m[3]]
	bodyStart := m[2]
	bodyEnd := m[3]
	lines := strings.Split(body, "\n")
	newLines := make([]string, 0, len(lines))
	prevBlank := false
	for _, line := range lines {
		if strings.TrimSpace(line) == "" {
			if prevBlank {
				continue
			}
			newLines = append(newLines, "")
			prevBlank = true
			continue
		}
		newLines = append(newLines, line)
		prevBlank = false
	}
	end := len(newLines)
	for end > 0 && strings.TrimSpace(newLines[end-1]) == "" {
		end--
	}
	newBody := strings.Join(newLines[:end], "\n")
	return locText[:bodyStart] + newBody + locText[bodyEnd:]
}

// Remove attribute localization lines for the given items (keeps desc/lore/summary...).
// If anchor is provided, adjust it for removed lines before the anchor.
func purgeAttributesForItems(locText string, itemNames []string, anchor *insertIndexRef) (string, *insertIndexRef) {
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return locText, anchor
	}
	body := locText[m[2]:m[3]]
	lines := strings.Split(body, "\n")
	prefixes := make([]string, len(itemNames))
	for i, name := range itemNames {
		prefixes[i] = fmt.Sprintf("DOTA_Tooltip_Ability_%s_", name)
	}
	kept := make([]string, 0, len(lines))
	removedIdx := []int{}
	for lineIdx, line := range lines {
		mk := regexp.MustCompile(`^\s*"([^"]+)"`).FindStringSubmatch(line)
		if len(mk) != 2 {
			kept = append(kept, line)
			continue
		}
		key := mk[1]
		prefixHit := ""
		for _, p := range prefixes {
			if strings.HasPrefix(key, p) {
				prefixHit = p
				break
			}
		}
		if prefixHit == "" {
			kept = append(kept, line)
			continue
		}
		suffix := strings.TrimPrefix(key, prefixHit)
		if shouldKeepNonAttributeSuffix(suffix) {
			kept = append(kept, line)
		} else {
			removedIdx = append(removedIdx, lineIdx)
		}
	}
	bodyStart := m[2]
	bodyEnd := m[3]
	newBody := strings.Join(kept, "\n")
	if anchor == nil {
		return locText[:bodyStart] + newBody + locText[bodyEnd:], nil
	}
	removedBefore := 0
	for _, idx := range removedIdx {
		if idx < anchor.Value {
			removedBefore++
		}
	}
	val := anchor.Value - removedBefore
	if val < 0 {
		val = 0
	}
	return locText[:bodyStart] + newBody + locText[bodyEnd:], &insertIndexRef{Value: val}
}

func findAnchorRef(locText, itemName, field string) *insertIndexRef {
	re := regexp.MustCompile(`"Tokens"\s*\{([\s\S]*?)\n\}`)
	m := re.FindStringSubmatchIndex(locText)
	if m == nil {
		return nil
	}
	body := locText[m[2]:m[3]]
	lines := strings.Split(body, "\n")
	target := fmt.Sprintf(`"%s"`, fmt.Sprintf("DOTA_Tooltip_Ability_%s_%s", itemName, field))
	for i, line := range lines {
		if strings.Contains(line, target) {
			return &insertIndexRef{Value: i + 1}
		}
	}
	return nil
}

// ---------- sync ----------

func syncEnhancePassiveAbilityValues(resolve func(string) string, resolveForWrite func(string) string) error {
	passiveRel := "game/dzsj/scripts/npc/item stats/shop1_items_enhance_passive.txt"
	abilityRel := "game/dzsj/scripts/npc/abilities/shop1_items_abilities_enhance.txt"

	passiveAbs := resolve(passiveRel)
	abilityAbs := resolve(abilityRel)

	if _, err := os.Stat(passiveAbs); err != nil {
		return fmt.Errorf("read enhance passive: %w", err)
	}
	if _, err := os.Stat(abilityAbs); err != nil {
		return fmt.Errorf("read enhance abilities: %w", err)
	}

	passiveKV, err := kv.ReadKVFile(passiveAbs)
	if err != nil {
		return fmt.Errorf("parse enhance passive kv: %w", err)
	}
	abilityKV, err := kv.ReadKVFile(abilityAbs)
	if err != nil {
		return fmt.Errorf("parse enhance abilities kv: %w", err)
	}

	passiveItems := kv.DetectRootItems(passiveKV)
	abilityItems := kv.DetectRootItems(abilityKV)

	for _, key := range passiveItems.Keys {
		passiveBlock, _ := passiveItems.GetObject(key)
		if passiveBlock == nil {
			continue
		}
		abilityBlock, _ := abilityItems.GetObject(key)
		if abilityBlock == nil {
			abilityBlock = kv.NewKVObject()
		}
		abilityBlock.Set("AbilityValues", passiveBlock.DeepClone())
		abilityItems.Set(key, abilityBlock)
	}

	if err := kv.WriteKVFile(resolveForWrite(abilityRel), abilityKV); err != nil {
		return fmt.Errorf("write enhance abilities kv: %w", err)
	}
	return nil
}

type syncBaseAbilityValuesParams struct {
	pairName          string
	stats             *kv.KVObject
	raw               *kv.KVObject
	fieldKeys         []string
	fieldKeys2        []string
	allowedExtraFields map[string]struct{}
	levelCfg          map[string]any
	transform         func(string, string) string
}

func syncBaseAbilityValues(p syncBaseAbilityValuesParams) {
	writeLevel := false
	if p.levelCfg != nil {
		if _, ok := p.levelCfg[p.pairName]; ok {
			writeLevel = true
		}
	}
	fieldTable2Set := map[string]struct{}{}
	for _, f := range p.fieldKeys2 {
		fieldTable2Set[f] = struct{}{}
	}

	for _, itemName := range p.stats.Keys {
		statsItem, _ := p.stats.GetObject(itemName)
		rawItem, _ := p.raw.GetObject(itemName)
		if statsItem == nil || rawItem == nil {
			continue
		}
		av, _ := rawItem.GetObject("AbilityValues")
		if av == nil {
			av = kv.NewKVObject()
		}

		// statsValues collects ALL values from stats that we might want to sync.
		statsValues := map[string]string{}
		for _, field := range p.fieldKeys {
			if v, ok := statsItem.GetString(field); ok {
				statsValues[field] = p.transform(field, v)
			}
		}
		if bonus, ok := statsItem.GetObject("BonusAttribute"); ok && bonus != nil {
			for _, k := range bonus.Keys {
				if v, ok := bonus.GetString(k); ok {
					statsValues[k] = p.transform(k, v)
				}
			}
		}


		// Only handle managed keys. Others (like "asdafa") are kept as-is.
		allManaged := map[string]struct{}{}
		for _, f := range p.fieldKeys {
			allManaged[f] = struct{}{}
		}
		for _, f := range p.fieldKeys2 {
			allManaged[f] = struct{}{}
		}
		for k := range p.allowedExtraFields {
			allManaged[k] = struct{}{}
		}

		for k := range allManaged {
			if k == "Level" {
				continue
			}
			if v, ok := statsValues[k]; ok {
				av.Set(k, v)
			} else {
				av.Delete(k)
			}
		}

		if writeLevel {
			av.Set("Level", "1")
		}

		rebuilt := kv.NewKVObject()
		inserted := false
		rebuiltFieldTable2 := map[string]string{}
		for _, f := range p.fieldKeys2 {
			if v, ok := statsItem.GetString(f); ok {
				rebuiltFieldTable2[f] = v
			}
		}

		for _, k := range rawItem.Keys {
			if k == "AbilityValues" && !inserted {
				for _, f := range p.fieldKeys2 {
					if v, ok := rebuiltFieldTable2[f]; ok {
						rebuilt.Set(f, v)
					}
				}
				rebuilt.Set("AbilityValues", av)
				inserted = true
				continue
			}
			if _, ok := fieldTable2Set[k]; ok {
				continue
			}
			rebuilt.Set(k, rawItem.Values[k])
		}

		if !inserted {
			for _, f := range p.fieldKeys2 {
				if v, ok := rebuiltFieldTable2[f]; ok {
					rebuilt.Set(f, v)
				}
			}
			rebuilt.Set("AbilityValues", av)
		}

		p.raw.Set(itemName, rebuilt)
	}
}

type expandItemsParams struct {
	rawItems      *kv.KVObject
	baseOrder     []string
	maxLevelMap   map[string]int
	managedFields map[string]struct{}
}

func expandItemsByLevel(p expandItemsParams) {
	newOrder := []string{}
	newItems := kv.NewKVObject()

	for _, baseKey := range p.baseOrder {
		base, _ := p.rawItems.GetObject(baseKey)
		if base == nil {
			continue
		}
		newOrder = append(newOrder, baseKey)
		newItems.Set(baseKey, base)

		baseAV, _ := base.GetObject("AbilityValues")
		if baseAV == nil {
			continue
		}
		baseAVKeys := append([]string{}, baseAV.Keys...)
		maxLevel := p.maxLevelMap[baseKey]
		if maxLevel <= 1 {
			continue
		}

		for lvl := 1; lvl <= maxLevel; lvl++ {
			key := fmt.Sprintf("%s_%d", baseKey, lvl)
			oldDerived, _ := p.rawItems.GetObject(key)
			cloned := base.DeepClone()
			cloned.Set("Shop", "-1")
			for _, k := range cloned.Keys {
				if k == "AbilityValues" {
					continue
				}
				if v, ok := cloned.GetString(k); ok {
					tokens := kv.SplitWhitespace(v)
					if shouldPickByLevel(v, tokens) {
						cloned.Set(k, pickByLevel(tokens, lvl-1))
					}
				}
			}

			if oldDerived != nil {
				for _, k := range oldDerived.Keys {
					if _, exists := cloned.Values[k]; exists {
						continue
					}
					if _, managed := p.managedFields[k]; managed {
						continue
					}
					cloned.Set(k, oldDerived.Values[k])
				}
			}

			// AbilityTextureName 派生：基于 base 名追加 -XX
			if baseTex, ok := base.GetString("AbilityTextureName"); ok {
				lvlStr := fmt.Sprintf("%02d", lvl)
				cloned.Set("AbilityTextureName", fmt.Sprintf("%s-%s", baseTex, lvlStr))
			}

			// ScriptFile 派生：沿用目录，文件名替换为 baseKey_lvl.lua
			if baseScript, ok := base.GetString("ScriptFile"); ok {
				lastSlash := strings.LastIndex(baseScript, "/")
				dir := ""
				if lastSlash >= 0 {
					dir = baseScript[:lastSlash+1]
				}
				cloned.Set("ScriptFile", fmt.Sprintf("%s%s_%d.lua", dir, baseKey, lvl))
			}

			avFinal := kv.NewKVObject()
			for _, field := range baseAVKeys {
				rawVal, ok := baseAV.GetString(field)
				if !ok {
					continue
				}
				if field == "Level" {
					avFinal.Set(field, fmt.Sprintf("%d", lvl))
					continue
				}
				tokens := kv.SplitWhitespace(rawVal)
				if shouldPickByLevel(rawVal, tokens) {
					avFinal.Set(field, pickByLevel(tokens, lvl-1))
				} else {
					avFinal.Set(field, rawVal)
				}
			}
			cloned.Set("AbilityValues", avFinal)
			newOrder = append(newOrder, key)
			newItems.Set(key, cloned)
		}
	}

	p.rawItems.Keys = []string{}
	p.rawItems.Values = map[string]kv.KVValue{}
	for _, k := range newOrder {
		p.rawItems.Set(k, newItems.Values[k])
	}
}

func shouldPickByLevel(raw string, tokens []string) bool {
	if len(tokens) <= 1 {
		return false
	}
	if strings.Contains(raw, "|") {
		return false
	}
	return true
}

func pickByLevel(tokens []string, idx int) string {
	if len(tokens) == 0 {
		return ""
	}
	if idx < 0 {
		idx = 0
	}
	if idx >= len(tokens) {
		idx = len(tokens) - 1
	}
	return tokens[idx]
}

// ---------- ability / level helpers ----------

func getMaxLevelFromStatsItem(item *kv.KVObject) int {
	if item == nil {
		return 1
	}
	for _, k := range item.Keys {
		if v, ok := item.GetString(k); ok {
			tokens := kv.SplitWhitespace(v)
			if len(tokens) > 1 {
				return len(tokens)
			}
		}
	}
	return 1
}

// ---------- bonus attribute order ----------

func getBonusAttributeOrder(tokens []kv.Token, itemName string) []string {
	order := []string{}
	i := 0
	for i < len(tokens) {
		tk := tokens[i]
		if tk.Typ == "str" && tk.Val == itemName {
			if i+1 < len(tokens) && tokens[i+1].Typ == "{" {
				i += 2
				depth := 1
				for i < len(tokens) && depth > 0 {
					cur := tokens[i]
					if cur.Typ == "{" {
						depth++
						i++
						continue
					}
					if cur.Typ == "}" {
						depth--
						i++
						continue
					}
					if depth == 1 && cur.Typ == "str" && cur.Val == "BonusAttribute" {
						if i+1 < len(tokens) && tokens[i+1].Typ == "{" {
							i += 2
							bDepth := 1
							for i < len(tokens) && bDepth > 0 {
								bt := tokens[i]
								if bt.Typ == "{" {
									bDepth++
									i++
									continue
								}
								if bt.Typ == "}" {
									bDepth--
									i++
									continue
								}
								if bDepth == 1 && bt.Typ == "str" {
									if i+1 < len(tokens) && tokens[i+1].Typ == "str" {
										order = append(order, bt.Val)
										i += 2
										continue
									}
								}
								i++
							}
							return order
						}
					}
					i++
				}
				break
			}
		}
		i++
	}
	return order
}

